INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'winix'), '5500', 'winix-5500-replacement-filter', 'air_purifier', 'replacement filter for winix 5500', '116130', NULL, NULL, NULL, 'Buyers should verify that their unit is the Winix 5500‑2 model and check the part number on the existing filter before ordering, as some listings also reference the AM80 variant.', '[{"q": "What part number is required for a replacement filter on a Winix 5500?", "a": "The Winix 5500‑2 requires the 116130 Filter H, as indicated in all product titles."}, {"q": "Is there a difference between OEM and third‑party filters for this model?", "a": "OEM filters are marked ‘Genuine Winix’, while third‑party options use the same 116130 code but are not manufactured by Winix; performance may vary."}, {"q": "Do the listings specify HEPA grade or size for the 116130 filter?", "a": "No; the titles do not mention a HEPA grade or any dimensions, so those details are unavailable."}]', 'Replacement filters for the Winix 5500 air purifier use the 116130 Filter H part. The official OEM version is sold by Winix, while third‑party sellers offer multi‑pack options. Both types provide the same model‑specific filtration, though HEPA grade details are not specified in the listings.', '["The Winix 5500‑2 uses the 116130 Filter H, confirmed across all listings.", "OEM filters are labeled ‘Genuine Winix’, while third‑party listings offer multi‑pack values.", "No HEPA grade or physical dimensions are provided in the titles."]', 'published') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.fa