INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'coway'), 'Airmega 2', 'coway-airmega-2-replacement-filter', 'air_purifier', 'coway airmega 2 replacement filter', NULL, NULL, NULL, NULL, 'Before purchasing, confirm that your Airmega 2 model matches the AP‑1512N sticker, as the listed filters are specifically for that variant and may not fit other Airmega 2 models.', '[{"q": "What filter part code is compatible with the Coway Airmega 2?", "a": "The listings do not provide a specific part code; the filters are sold under the brand name COWAY Airmega Mighty2 and are intended for the Airmega 2 (AP‑1512N) model."}, {"q": "Are OEM filters from Coway available, and how do they differ from third‑party replacements?", "a": "Yes, OEM filters such as Fresh Starter Plus, Allergen Plus and Intense Smoke Plus are sold by Coway; they are branded and typically priced higher than third‑party multi‑pack options."}, {"q": "What filtration features and maintenance requirements are noted in the title?", "a": "The titles mention Fresh Starter, Allergen, and Intense Smoke Plus, indicating different filtration stages, but no maintenance schedule is specified."}]', 'The Coway Airmega 2 uses a genuine replacement filter sold under the brand name COWAY Airmega Mighty2. OEM versions such as Fresh Starter Plus, Allergen Plus, and Intense Smoke Plus are available, as well as multi‑pack third‑party options like the 2‑Pack replacement for the AP‑1512N. Verify the exact model sticker before ordering.', '["Compatibility: Genuine COWAY Airmega Mighty2 filters fit the Airmega 2 (AP‑1512N) model.", "Filtration features: OEM variants include Fresh Starter Plus, Allergen Plus, Intense Smoke Plus; third‑party 2‑Pack offers cost‑effective replacement.", "Buying options: OEM filters are single units; third‑party options available in multi‑packs."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
