INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'coway'), 'MAX2 Replacement', 'coway-max2-replacement-replacement-filter', 'air_purifier', 'coway max2 filter replacement', 'AP-2015-FP', NULL, NULL, NULL, 'Buyers should confirm the exact model number and part code on their Coway MAX2 unit, as filters listed for the 400/400S series differ from those for the 250/250S models shown in the data.', '[{"q": "What part code is required for a replacement filter for the Coway MAX2 (Airmega 400/400S)?", "a": "The official Coway replacement filter for the MAX2 is identified by part number AP-2015-FP."}, {"q": "Are there differences between OEM Coway filters and third‑party replacements for the MAX2?", "a": "OEM filters are made by Coway and match the original specifications, while third‑party filters are compatible alternatives often sold in multi‑packs and may vary in branding but use the same AP-2015-FP design."}, {"q": "What filtration technologies does the MAX2 replacement filter provide?", "a": "The filter combines a True HEPA element with an active carbon layer to capture fine particles and reduce odors."}]', 'Replacement filters compatible with the Coway MAX2 (Airmega 400/400S) model are identified by the part code AP-2015-FP. The filter combines a True HEPA element with an active carbon layer for particulate and odor removal. Both OEM Coway filters and third‑party multi‑pack replacements are offered for this unit.', '["AP-2015-FP is the official filter code for Coway MAX2 (Airmega 400/400S) units", "The filter provides True HEPA filtration plus active carbon for particles and odors", "Both genuine Coway OEM filters and multi‑pack third‑party replacements are available"]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'coway'), 'Noble 2', 'coway-noble-2-replacement-filter', 'air_purifier', 'coway noble 2 filter', 'AP-2021A', 'H13', NULL, NULL, 'Verify that your specific Coway Noble 2 unit requires the AP-2021A filter by checking the model sticker, as listings also reference other Coway models like the Airmega Max2 which use different filters. Do not assume cross-compatibility with other Coway air purifier series without confirming the exact part number.', '[{"q": "What is the correct filter part number for the Coway Noble 2?", "a": "The correct filter part number is AP-2021A, which is explicitly listed as compatible with the Coway Noble Air Purifier in multiple product titles."}, {"q": "Are there differences between OEM and third-party filters for this model?", "a": "While the provided listings primarily show third-party replacements for the AP-2021A, genuine OEM filters are also available. Third-party options often come in multi-packs (e.g., 2 sets) and may offer cost savings compared to single OEM units."}, {"q": "What filtration features does the AP-2021A filter include?", "a": "The AP-2021A filter assembly includes H13 HEPA filtration and customized pre-filters, designed to capture fine particulate matter and larger debris respectively."}]', 'The Coway Noble 2 air purifier utilizes the AP-2021A replacement filter assembly. Listings indicate this filter features H13 HEPA filtration combined with customized pre-filters. Both genuine OEM units and third-party compatible replacements are available, with multi-pack options offering value for users requiring periodic maintenance of their air purification system.', '["The specific filter part number for the Coway Noble 2 is AP-2021A, as identified in compatible replacement listings.", "The filtration system includes H13 HEPA technology and customized pre-filters to capture airborne particles.", "Consumers can choose between single-unit replacements and two-set multi-packs from various third-party manufacturers."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
