INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'HFT600', 'honeywell-hft600-replacement-filter', 'air_purifier', 'honeywell replacement filter hft600', 'HFT600', NULL, NULL, NULL, 'Verify that your specific Honeywell unit is labeled HFT600, as listings indicate cross-compatibility with HEV615 and HEV620 series models. Ensure the filter type matches the ''wicking'' specification to avoid ordering incompatible media.', '[{"q": "What is the correct filter part number for the Honeywell HFT600?", "a": "The correct filter part number is HFT600. Listings also indicate that this filter is compatible with the Honeywell HEV615 and HEV620 series."}, {"q": "Are there third-party alternatives to the official Honeywell HFT600 filter?", "a": "Yes, third-party manufacturers such as Lemige offer 6-pack replacement filters specifically labeled for the HFT600, providing a multi-pack option compared to the 3-count official listing."}, {"q": "What type of filtration technology does the HFT600 filter use?", "a": "The HFT600 filter uses wicking technology, as explicitly described in the product titles. Specific HEPA grades are not stated in the available listing data."}]', 'The Honeywell HFT600 utilizes a wicking filter system, with the model number HFT600 serving as the primary compatibility identifier. While specific HEPA grades are not explicitly detailed in the provided listings, the device relies on wicking technology for filtration. Buyers can select between official Honeywell replacement units and third-party multi-packs, such as 6-count options from brands like Lemige, ensuring availability for both single and bulk maintenance needs.', '["The HFT600 is the designated filter code for this Honeywell humidifier, with compatibility also noted for HEV615 and HEV620 series models.", "Listings specify ''wicking'' filters, indicating a specific filtration mechanism, though explicit HEPA grade classifications are not present in the source data.", "Consumers have options ranging from 3-count OEM-style packs to 6-count third-party value packs from manufacturers like Lemige."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'FC100A1037', 'honeywell-fc100a1037-replacement-filter', 'air_purifier', 'honeywell replacement filter fc100a1037', 'FC100A1037', 'MERV 11', 'rectangular', '{"length_in": 20, "width_in": 25, "height_in": 4}', 'Verify your specific Honeywell FC100A1037 model sticker to ensure the 20" x 25" x 4" dimensions match your unit, as filter sizes can vary across similar purifier models. Confirm the MERV 11 rating aligns with your device''s airflow requirements before purchasing.', '[{"q": "What is the correct filter part number for the Honeywell FC100A1037?", "a": "The listings identify the filter as FC100A1037, which is a 20\" x 25\" x 4\" pleated filter."}, {"q": "Are there third-party replacement options for this filter?", "a": "Yes, listings show third-party 2-packs of the FC100A1037 filter that include a same-day supply filter change reminder."}, {"q": "What filtration grade does the FC100A1037 filter provide?", "a": "The product titles specify a MERV 11 filtration grade for the pleated air filter."}]', 'The Honeywell FC100A1037 air purifier utilizes a rectangular pleated filter measuring 20 inches by 25 inches by 4 inches. Listings confirm compatibility with MERV 11 filtration standards. Buyers can select between official Honeywell units and third-party multi-pack replacements, such as 2-packs that include supply filter change reminders for consistent maintenance.', '["Compatible filters are rectangular, pleated, and measure 20\" x 25\" x 4\".", "Listed products specify MERV 11 filtration performance for the FC100A1037 model.", "Options include single OEM units and third-party 2-packs with change reminders."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'FC100A1029', 'honeywell-fc100a1029-replacement-filter', 'air_purifier', 'honeywell replacement filter fc100a1029', 'FC100A1029', NULL, 'rectangular', '{"length_in": 15.94, "width_in": 24.86, "height_in": 4.38}', 'Before purchasing, verify your HVAC system''s filter slot dimensions against the actual filter size of 15.94 x 24.86 x 4.38 inches. Ensure the model number FC100A1029 matches your existing unit''s sticker to guarantee compatibility.', '[{"q": "What is the correct filter part number for the Honeywell FC100A1029?", "a": "The compatible part number is FC100A1029, which corresponds to a 16x25x4 media air filter."}, {"q": "Are there differences between OEM and third-party filters for this model?", "a": "Yes, genuine Honeywell filters are available, while third-party options often provide value through multi-packs and may include extras like cleaning cloths or disposal bags."}, {"q": "What filtration level does the FC100A1029 replacement filter provide?", "a": "These filters typically offer a MERV 11 rating, designed for pleated HVAC air filtration to capture household dust and allergens."}]', 'The Honeywell FC100A1029 air purifier requires a 16x25x4 media air filter, typically featuring a MERV 11 filtration rating. This specific model is compatible with official Honeywell OEM replacements and various third-party multi-packs. Users should verify actual dimensions, approximately 15.94 x 24.86 x 4.38 inches, to ensure a proper fit within the HVAC cabinet.', '["Compatible with 16x25x4 media air filters specifically designed for the FC100A1029 model.", "Features MERV 11 filtration efficiency for capturing airborne particles in HVAC systems.", "Available in genuine Honeywell OEM singles or cost-effective third-party multi-packs (2-pack or 5-pack)."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), '24000', 'honeywell-24000-replacement-filter', 'air_purifier', 'honeywell hepa filter 24000', '50250-S', 'HEPA', NULL, NULL, 'Verify your specific Honeywell model number (24000, 24500, or 52500) against the product listing to ensure compatibility, as these models share the 50250-S filter system. Always check the unit''s sticker for the exact part number before ordering.', '[{"q": "What is the correct filter part number for the Honeywell 24000 air purifier?", "a": "The correct filter part number is 50250-S. This filter is compatible with Honeywell models 24000, 24500, and 52500."}, {"q": "Are the replacement filters for the Honeywell 24000 OEM or third-party?", "a": "The listed products are third-party replacements compatible with the Honeywell 24000. They are not manufactured by Honeywell but are designed to fit the 50250-S filter system."}, {"q": "What filtration components are included in the 50250-S replacement sets?", "a": "The 50250-S replacement sets include HEPA filters and carbon pre-filters. Some listings offer single HEPA filters, while others provide multi-packs containing both HEPA and carbon pre-filters."}]', 'The Honeywell 24000 air purifier utilizes the 50250-S filter system, which consists of HEPA and carbon pre-filters. Replacement options include single HEPA units or multi-pack sets containing both HEPA and carbon pre-filters. Both OEM and third-party compatible filters are available for this model, ensuring continued filtration performance for the 24000, 24500, and 52500 series units.', '["The official filter part number for the Honeywell 24000 is 50250-S, which is also compatible with models 24500 and 52500.", "Replacement sets typically include HEPA filters and carbon pre-filters, with options ranging from single units to multi-packs.", "Buyers can choose between single HEPA replacements or complete sets including carbon pre-filters from various third-party manufacturers."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), '20X25X4', 'honeywell-20x25x4-replacement-filter', 'air_purifier', 'honeywell filters 20x25x4', 'FC100A1037', NULL, NULL, '{"length_in": 20, "width_in": 25, "height_in": 4}', 'Buyers should confirm that their unit lists the 20X25X4 dimensions and part number FC100A1037 on the filter label before purchasing, as some listings bundle multiple filters or use different MERV ratings.', '[{"q": "What is the official Honeywell replacement filter part number for a 20X25X4 air purifier?", "a": "The OEM part number is FC100A1037, which fits a 20 × 25 × 4‑inch rectangular filter slot."}, {"q": "Are third‑party filters compatible with the Honeywell 20X25X4, and how do they differ from OEM?", "a": "Third‑party filters such as Filtrete with the same 20 × 25 × 4 dimensions are compatible, but they may offer different MERV ratings (e.g., MERV 12) and are sold in value multi‑packs rather than as genuine Honeywell OEM parts."}, {"q": "What filtration performance can I expect from these replacement filters?", "a": "Honeywell OEM filters are rated MERV 11, while Filtrete alternatives provide MERV 11 or MERV 12, capturing dust, pollen and other particulates according to their rating."}]', 'Replacement filters for the Honeywell 20X25X4 air purifier use the OEM part code FC100A1037 and are rated MERV 11. Both genuine Honeywell packs and third‑party multi‑pack options (e.g., Filtrete MERV 12) are sold, providing compatible rectangular 20 × 25 × 4‑inch pleated filters. These filters fit the standard rectangular slot and maintain airflow while capturing dust and pollen.', '["OEM Honeywell filter code FC100A1037 matches 20×25×4 in dimensions and is MERV 11.", "Third‑party Filtrete options also fit the size, offering MERV 12 or MERV 11 ratings in multi‑pack values.", "Both OEM single packs and value multi‑packs are available, allowing choice between brand‑specific and cost‑effective replacements."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), '16X25X4', 'honeywell-16x25x4-replacement-filter', 'air_purifier', 'honeywell filters 16x25x4', 'FC100A1029', NULL, NULL, '{"length_in": 16, "width_in": 25, "height_in": 4}', 'Verify the exact model number and part code on your unit’s filter label before purchasing, as some listings use generic dimensions or third‑party branding that may not match the original Honeywell specification.', '[{"q": "What part code should I look for when buying a replacement filter for a Honeywell 16x25x4 unit?", "a": "The official Honeywell part code listed for this size is FC100A1029; filters bearing this code are designed to match the 16 × 25 × 4 in dimensions."}, {"q": "Are OEM Honeywell filters different from third‑party multi‑pack replacements?", "a": "OEM filters are manufactured by Honeywell and typically sold singly, while third‑party sellers offer value packs (2‑ or 3‑packs) that may use the same dimensions but are not branded Honeywell."}, {"q": "What filtration grades are available for the 16x25x4 filter?", "a": "Listings show MERV 11 as the most common grade, with some MERV 8 options; higher MERV ratings provide finer particle capture."}]', 'Replacement filters that fit a Honeywell 16x25x4 air purifier are identified by the part code FC100A1029 and are commonly rated MERV 11, though MERV 8 options also exist. Both genuine Honeywell OEM filters and third‑party multi‑pack replacements are sold for this size, making them suitable for standard HVAC systems and easy to install.', '["The 16x25x4 size corresponds to part code FC100A1029 and is offered in MERV 11 and MERV 8 grades.", "OEM Honeywell filters are available singly, while third‑party sellers provide multi‑pack (2‑ or 3‑pack) options.", "All listings specify the same nominal dimensions (16 × 25 × 4 in), ensuring physical compatibility."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), '20X25X4 Merv 11', 'honeywell-20x25x4-merv-11-replacement-filter', 'air_purifier', 'honeywell filter 20x25x4 merv 11', 'FC100A1037', NULL, 'rectangular', '{"length_in": 20, "width_in": 25, "height_in": 4}', 'Verify that your specific Honeywell unit requires the FC100A1037 part number and 20" x 25" x 4" dimensions before ordering. Note that listings include variants such as 5-packs and bundles with reminders, so ensure the pack size matches your maintenance schedule.', '[{"q": "What is the official filter part number for the Honeywell 20X25X4 Merv 11?", "a": "The official filter part number is FC100A1037. It is a pleated air filter measuring 20 inches by 25 inches by 4 inches with a MERV 11 rating."}, {"q": "Are there differences between OEM and third-party replacements for this filter?", "a": "OEM filters are manufactured by Honeywell and often include features like same-day supply filter change reminders. Third-party replacements, such as those from Homequip, may include additional accessories like disposal bags but are not made by Honeywell."}, {"q": "What filtration features and maintenance options are available for this filter?", "a": "The filter uses pleated media with a MERV 11 rating. Maintenance options include buying in 2-packs or 5-packs, and some listings provide filter change reminders or disposal bags to facilitate replacement."}]', 'The Honeywell 20X25X4 Merv 11 air purifier utilizes the FC100A1037 pleated filter. This rectangular media measures 20 inches by 25 inches by 4 inches and provides MERV 11 filtration. Buyers can select official Honeywell OEM bundles or third-party replacement packs. Listings indicate availability in 2-packs and 5-packs, often including filter change reminders or disposal bags for convenient maintenance.', '["The compatible official filter part number is FC100A1037, with dimensions of 20\" x 25\" x 4\".", "Filtration is rated MERV 11 using pleated media, available in both OEM and third-party formats.", "Purchase options include 2-packs and 5-packs, with some listings offering same-day supply reminders or disposal bags."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'A Hac 504', 'honeywell-a-hac-504-replacement-filter', 'air_purifier', 'honeywell filter a hac 504', 'Filter A (HAC-504)', NULL, NULL, NULL, 'Ensure your device matches the HAC-504 or HAC-504AW specification found on the unit''s base or existing filter. Verify compatibility with cool mist humidifier models like the HCM 350 before purchasing.', '[{"q": "Which replacement filter is compatible with the Honeywell HAC-504?", "a": "The Honeywell HAC-504 is compatible with Filter A (HAC-504 or HAC-504AW) wicking filters."}, {"q": "Are there official Honeywell brand filters available for this model?", "a": "Yes, Honeywell offers official Filter A wicking filters, typically sold in multi-packs for cool mist humidifiers."}, {"q": "What is the difference between OEM and third-party filters for the HAC-504?", "a": "OEM filters are genuine Honeywell products, while third-party options like Durabasics offer compatible alternatives often in larger value packs."}]', 'The Honeywell A Hac 504 requires the Honeywell Filter A, also identified by part number HAC-504 or HAC-504AW. These wicking filters are designed for cool mist humidifiers. Consumers can choose between official Honeywell 3-packs or third-party multi-packs, such as 4-packs, to maintain optimal performance and moisture output.', '["Compatible with Honeywell Filter A (HAC-504/HAC-504AW) wicking filters.", "Available in both genuine Honeywell OEM packs and third-party replacement options.", "Designed specifically for cool mist humidifier models like the HCM 350 series."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'C White Pack Of 2', 'honeywell-c-white-pack-of-2-replacement-filter', 'air_purifier', 'honeywell c replacement filter white pack of 2', 'C', NULL, NULL, NULL, 'Verify your exact Honeywell model number (e.g., HC-888N, HCM-890, HEV-320) against the product listing, as ''Filter C'' is specific to these humidifier series and may not fit other Honeywell air purifiers or humidifier variants.', '[{"q": "What is the official part number for the Honeywell C White Pack Of 2 filter?", "a": "The official filter code is ''C''. It is listed as a replacement filter for Honeywell humidifiers including the HC-888N, HCM-890, and HEV-320 series."}, {"q": "Is the Honeywell C filter an OEM product or a third-party replacement?", "a": "Both options are available. ASIN B0CXB24VBJ and B07VJK138N are genuine Honeywell products, while ASIN B07M5GQJ3W and B0B84L9L27 are third-party replacements compatible with the same models."}, {"q": "What filtration features are mentioned for the Honeywell C filter?", "a": "Third-party listings describe the filter as a ''high absorbency wicking filter.'' No specific HEPA grade or micron rating is explicitly stated in the provided product titles."}]', 'The Honeywell C White Pack Of 2 utilizes the official Filter C replacement part. Listings indicate compatibility with Honeywell humidifier models such as the HC-888N, HCM-890, and HEV-320 series. Both genuine Honeywell OEM filters and third-party high-absorbency wicking replacements are available in single or two-pack configurations. Buyers should verify their specific model number to ensure correct fitment for their device.', '["The official filter code is ''C'', compatible with Honeywell HC-888N, HCM-890, and HEV-320 series humidifiers.", "Listings describe the filter as a high-absorbency wicking filter, though specific HEPA grades are not explicitly stated in the titles.", "Purchase options include genuine Honeywell OEM packs (1 or 2 filters) and third-party replacements, with the latter often marketed for high absorbency."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'C Hc 888N', 'honeywell-c-hc-888n-replacement-filter', 'air_purifier', 'honeywell filter c hc 888n', NULL, NULL, NULL, NULL, 'Before purchasing, confirm the exact Honeywell C Hc 888N model sticker or part number, as some listings also reference HC‑888 and HC‑888N/HCM‑890/HEV‑320 series, so verify your unit.', '[{"q": "What filter part code is compatible with the Honeywell C Hc 888N?", "a": "The titles only mention \"Filter C\"; no specific Honeywell part code is listed. The filter is identified by the generic Filter C designation."}, {"q": "Are the listed filters OEM or third‑party?", "a": "All listed products are third‑party replacements; none are manufactured by Honeywell."}, {"q": "What filtration features are highlighted in the listings?", "a": "The titles emphasize \"High Absorbency Wicking Filter\" for one product and mention multi‑pack options, but no HEPA grade or specific filtration technology is specified."}]', 'The Honeywell C Hc 888N uses a Filter C humidifier filter. Official filter part codes and HEPA grades are not listed in the titles, but OEM Honeywell filters are available. Third‑party manufacturers also offer multi‑pack replacements that fit the same model and are sold in various pack sizes.', '["Compatible with Honeywell HC‑888N and related HC‑888 variants", "All titles reference Filter C, the standard part for this model", "OEM Honeywell filters and third‑party multi‑pack replacements are available"]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'C Hc 888', 'honeywell-c-hc-888-replacement-filter', 'air_purifier', 'honeywell filter c hc 888', 'Filter C', NULL, NULL, NULL, 'Verify that your specific unit is labeled HC-888 or HC-888N, as the listings indicate this filter is also compatible with HCM-890 and HEV-320 series models. Do not assume compatibility with other Honeywell humidifier series without checking the model sticker on the device.', '[{"q": "What is the specific part number for the Honeywell HC-888 filter?", "a": "The listings identify the replacement part as ''Filter C''. This part is explicitly listed as compatible with the Honeywell HC-888 and HC-888N models."}, {"q": "Is it better to buy the OEM Honeywell filter or a third-party replacement?", "a": "The OEM option is a single-pack white filter manufactured by Honeywell. Third-party options, such as the Lemige 4-pack or the 2-pack high absorbency wicking filter, offer more units per purchase but are not manufactured by Honeywell."}, {"q": "What filtration features are mentioned for the HC-888 Filter C?", "a": "The product titles describe the filter as a ''high absorbency wicking filter''. No specific HEPA grade or micron rating is stated in the provided listings."}]', 'The Honeywell HC-888 and HC-888N humidifiers utilize the official Filter C replacement part. This specific filter is designed for high absorbency wicking and is compatible with the HC-888, HC-888N, HCM-890, and HEV-320 series. Buyers can select between single-pack OEM units from Honeywell or cost-effective multi-pack third-party replacements that maintain the same filtration specifications and physical compatibility.', '["The correct replacement part is identified as Filter C, which is cross-compatible with Honeywell models HC-888, HC-888N, HCM-890, and HEV-320.", "Listings describe the filter as a high absorbency wicking filter, though specific HEPA grades or exact dimensional measurements are not provided in the product titles.", "Consumers have options ranging from official single-pack Honeywell filters to third-party value packs containing two or four units for extended maintenance intervals."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'E Hc 14', 'honeywell-e-hc-14-replacement-filter', 'air_purifier', 'honeywell filter e hc 14', 'Filter E', NULL, NULL, NULL, 'Verify your specific Honeywell model sticker, as listings confirm compatibility with HC-14, HC-14V1, and HC-14N variants. Ensure your unit matches these designations before ordering to guarantee fit.', '[{"q": "What is the correct filter part number for the Honeywell E Hc 14?", "a": "The correct filter is designated as Filter E. It is compatible with the Honeywell HC-14 series, including HC-14, HC-14V1, and HC-14N models."}, {"q": "Are there OEM Honeywell filters available in these listings?", "a": "No, the provided listings feature third-party replacement filters. Options include single packs and three-packs, with some described as ''Upgraded Blue Mesh'' versions."}, {"q": "What filtration features are mentioned for the Honeywell E Hc 14 filter?", "a": "Listings mention an ''Upgraded Blue Mesh'' design for certain third-party replacements. No specific HEPA grade or filtration efficiency metrics are stated in the product titles."}]', 'The Honeywell E Hc 14 utilizes the Filter E replacement cartridge. Available options include single units and three-pack value sets from third-party manufacturers. Listings indicate compatibility with the HC-14 series, including HC-14V1 and HC-14N variants. Buyers can select between standard and upgraded blue mesh versions. No specific HEPA grade or dimensional data is provided in the source titles.', '["The official filter designation for the Honeywell E Hc 14 is Filter E, compatible with HC-14, HC-14V1, and HC-14N models.", "Third-party replacements are available in single units or three-pack configurations, with some listings specifying an ''Upgraded Blue Mesh'' design.", "No OEM Honeywell-branded filters appear in the provided listings; all identified products are third-party replacements."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'Hepa G 2 Pack', 'honeywell-hepa-g-2-pack-replacement-filter', 'air_purifier', 'honeywell hepa replacement filter g 2 pack', 'HRF-G1/HRF-G2', 'HEPA', NULL, NULL, 'Verify your specific Honeywell air purifier model number (e.g., HPA020B, HPA030B) against the HRF-G1/HRF-G2 part number before ordering. Compatibility varies by series, so ensure your unit is listed in the HPA020, HPA030, HPA075/080, or HPA175/180 families.', '[{"q": "What is the part number for the Honeywell Hepa G 2 Pack filter?", "a": "The official filter code is HRF-G1/HRF-G2. This part number is compatible with Honeywell HPA020, HPA030, HPA075, HPA080, HPA175, and HPA180 series air purifiers."}, {"q": "Is the Honeywell Genuine HEPA Air Purifier Filter G the same as third-party HRF-G filters?", "a": "The Honeywell Genuine filter is the OEM product. Third-party filters are labeled as ''Compatible with'' or ''Replacement for'' the HRF-G1/HRF-G2 code. While both serve the same function, the genuine filter is manufactured by Honeywell, whereas third-party options are made by other vendors."}, {"q": "What filtration features do these replacement filters offer?", "a": "The listings identify these as HEPA filters. Specific third-party titles mention protection against allergies, pollen, and wildfire smoke, indicating high-efficiency particulate filtration capabilities."}]', 'The Honeywell Hepa G 2 Pack utilizes the HRF-G1/HRF-G2 filter code. These are HEPA-grade replacement filters designed for specific Honeywell air purifier series. Both genuine OEM 2-packs and third-party compatible multi-packs are available for purchase, offering options for allergy and wildfire protection.', '["The official filter part code is HRF-G1/HRF-G2, compatible with Honeywell HPA020, HPA030, HPA075, HPA080, HPA175, and HPA180 series.", "Listings specify HEPA filtration capabilities, with some third-party options highlighting protection against allergies, pollen, and wildfire smoke.", "Buyers can choose between genuine Honeywell 2-packs and third-party compatible filters, including 2-pack and 4-pack value options."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'H 2 Pack', 'honeywell-h-2-pack-replacement-filter', 'air_purifier', 'honeywell h filter 2 pack', 'HRF-H2', 'True HEPA', NULL, NULL, 'Ensure your device requires Filter H or part number HRF-H2 by checking the model sticker on your air purifier. Verify compatibility with specific series like HPA050 or HHT055 before ordering.', '[{"q": "Which specific filter code is required for the Honeywell H 2 Pack?", "a": "The required part number is HRF-H2, also known as Filter H, which is available in official 2-pack configurations for compatible air cleaners."}, {"q": "What is the difference between OEM and third-party replacement filters for this model?", "a": "Official Honeywell filters are genuine OEM replacements, while third-party options often provide larger quantities and may include additional HRF-B1 activated carbon pre-filters."}, {"q": "What types of pollutants does the HRF-H2 True HEPA filter target?", "a": "These filters are designed to capture airborne allergens such as wildfire smoke, pollen, pet dander, and household dust to improve indoor air quality."}]', 'The Honeywell H 2 Pack air purifier utilizes the HRF-H2 (Filter H) True HEPA replacement filter. These filters target airborne allergens including smoke, pollen, pet dander, and dust. Consumers can choose between official Honeywell OEM 2-packs or third-party multi-packs that often include activated carbon pre-filters for enhanced odor reduction.', '["Compatible with HRF-H2 (Filter H) specifications for models like HPA050 and HHT055.", "True HEPA filtration captures microscopic particles such as wildfire smoke and pet dander.", "Available in official Honeywell 2-packs or high-volume third-party bundles with pre-filters."]', 'enriched