INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'North P3', 'honeywell-north-p3-replacement-filter', 'air_purifier', 'honeywell north p3 filter', '75SCP100L', NULL, NULL, '{"length_in": 7.0, "width_in": 3.5, "height_in": 2.75}', 'Always verify your exact Honeywell North P3 model sticker and required cartridge part number before ordering, as listings include diverse variations such as organic vapor cartridges, multi-purpose filters, and particulate-specific options.', '[{"q": "What replacement filter parts fit the Honeywell North P3?", "a": "Compatible parts identified in the product listings include the 75SCP100L Defender Multi-Purpose Cartridge, 7583P100L Cartridge and Filter Combination, 7581P100L Organic Vapor P100 Cartridge, and 068-7580P100 P100 Particulate Filter."}, {"q": "What types of filtration features are available for these replacements?", "a": "Available options include P100 particulate filtration, organic vapor protection, and multi-purpose cartridge combinations."}, {"q": "What package quantities are available for purchase?", "a": "Replacement filters are available in 2-packs as well as bulk case quantities containing 144 packs."}]', 'The Honeywell North P3 uses compatible replacement filters and cartridges such as the 75SCP100L Defender Multi-Purpose Cartridge with P100 Filter, 7583P100L Cartridge and Filter Combination, 7581P100L Organic Vapor P100 Respirator Cartridge, and 068-7580P100 P100 Particulate Filter. Both OEM and multi-pack options are available across various configurations.', '["Compatible with specific Honeywell North filter part numbers including 75SCP100L, 7583P100L, 7581P100L, and 068-7580P100.", "Listings include multi-purpose cartridges, organic vapor options, and P100 particulate filters featuring P100 filtration.", "Buying options range from 2-packs to bulk case quantities of 144 units."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'Hfd 120 Q', 'honeywell-hfd-120-q-replacement-filter', 'air_purifier', 'honeywell hfd 120 q replacement filters', 'HFD-120-Q', 'HEPA', NULL, NULL, 'Verify that your Honeywell air purifier is specifically the HFD-120-Q QuietClean model, as other Honeywell models may use different filter shapes or part numbers. Cross-reference the part number on your existing filter or device sticker with the HFD-120-Q code to ensure a proper fit.', '[{"q": "What is the correct replacement filter part number for the Honeywell HFD-120-Q?", "a": "The correct replacement filter part number is HFD-120-Q. This filter is designed for the Honeywell QuietClean air purifier and is compatible with units identified by this specific model code."}, {"q": "Are there differences between OEM and third-party HFD-120-Q filters?", "a": "Third-party filters, such as those from CFS or other brands, are labeled as compatible replacements and are often sold in multi-packs (2 or 4). While they offer similar HEPA and carbon filtration, they are not manufactured by Honeywell, so buyers should check reviews for fit and performance consistency."}, {"q": "What filtration features does the HFD-120-Q filter provide?", "a": "The HFD-120-Q filter provides HEPA filtration to capture fine particles and includes an activated carbon component to reduce odors. This combination is standard for the QuietClean series to maintain indoor air quality."}]', 'The Honeywell HFD-120-Q QuietClean air purifier utilizes the HFD-120-Q replacement filter. Listings indicate this filter features HEPA filtration with activated carbon. Both OEM and third-party replacements are available in 2-pack and 4-pack configurations. Buyers should verify their specific unit model to ensure compatibility with the HFD-120-Q part number before purchasing.', '["The official filter part code for the Honeywell HFD-120-Q is HFD-120-Q, which is compatible with the QuietClean purifier.", "Replacement filters feature HEPA filtration combined with activated carbon to capture particles and odors.", "Third-party replacements are available in 2-pack and 4-pack quantities, offering cost-effective options compared to single OEM units."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
