INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), '50250 S Replacement', 'honeywell-50250-s-replacement-replacement-filter', 'air_purifier', 'honeywell 50250 s hepa filter replacement', '24000', 'H13', NULL, NULL, 'Buyers should confirm the exact model sticker or part number on their Honeywell 50250 S unit, as listings also reference compatible models such as 24000, 24500, and 52500, to ensure the correct replacement filter is ordered.', '[{"q": "What part number filter fits the Honeywell 50250 S?", "a": "The replacement filter uses the OEM part number 24000, which is listed across the product titles."}, {"q": "Are OEM filters different from third‑party replacements?", "a": "OEM filters are manufactured by Honeywell and carry the official part number, while third‑party kits are compatible replacements that may bundle HEPA and carbon pre‑filters but are not made by Honeywell."}, {"q": "What filtration grade and features do these filters provide?", "a": "Some listings specify an H13 HEPA grade and include activated carbon pre‑filters for dust, VOCs, and odor reduction."}]', 'Replacement filters for the Honeywell 50250 S air purifier use the OEM part number 24000 and are available in an H13 HEPA grade. Both genuine Honeywell (OEM) filters and third‑party multi‑pack kits that include HEPA and carbon pre‑filters are offered, providing compatible options for the unit today.', '["Filters with OEM part number 24000 fit Honeywell 50250 S models.", "Available in H13 HEPA grade with carbon pre‑filter options.", "OEM genuine filters and lower‑cost third‑party multi‑pack sets are sold."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, d