INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'T Model HFT600PFC', 'honeywell-t-model-hft600pfc-replacement-filter', 'air_purifier', 'honeywell replacement filters t model hft600pfc', 'HFT600T', NULL, NULL, NULL, 'Verify your specific Honeywell T Model HFT600PFC model sticker to ensure compatibility, as listings reference HFT600T and HFT600PDQ variants. Confirm the filter type matches your unit''s wicking mechanism before ordering.', '[{"q": "What is the correct filter part number for the Honeywell T Model HFT600PFC?", "a": "The correct part number is HFT600T. Listings also indicate compatibility with part number HFT600PDQ."}, {"q": "Are there OEM and third-party options available for this filter?", "a": "Yes, third-party replacements are available in multi-packs (4, 6, and 8 units). The scraped listings do not explicitly identify an OEM Honeywell-branded product, only third-party compatible filters."}, {"q": "What type of filtration does the HFT600T filter provide?", "a": "The HFT600T is identified as a wicking filter. Specific HEPA grades or filtration metrics are not stated in the product titles."}]', 'The Honeywell T Model HFT600PFC utilizes the HFT600T replacement wicking filter, also referenced as HFT600PDQ. This component is compatible with Honeywell HEV615 and HEV620 humidifier models. While specific HEPA grades are not listed, the filter serves as a wicking element. Both OEM and third-party multi-pack replacements are available for purchase.', '["The primary replacement part number is HFT600T, with HFT600PDQ listed as a comparable variant.", "The filter is a wicking type designed for Honeywell HEV615 and HEV620 humidifier models.", "Third-party options are available in 4, 6, and 8-pack configurations, offering value alternatives to single units."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'Humidifier T HFT600 Blue White', 'honeywell-humidifier-t-hft600-blue-white-replacement-filter', 'air_purifier', 'honeywell humidifier replacement filter t hft600 blue white', 'Filter T', NULL, NULL, NULL, 'Verify that your specific Honeywell Humidifier T HFT600 Blue White unit matches the ''Filter T'' requirement, as listings indicate cross-compatibility with HEV615 and HEV620 models. Ensure the model sticker on your device confirms HFT600 or a listed compatible variant before ordering.', '[{"q": "What is the specific filter part code for the Honeywell HFT600?", "a": "The specific filter part code identified in the listings is ''Filter T''. This wicking filter is explicitly listed as compatible with the HFT600 model."}, {"q": "Are there differences between OEM and third-party filters for this model?", "a": "OEM filters are manufactured by Honeywell and typically sold in 1-packs. Third-party replacements, such as those from Lemige, are available in multi-packs (3 to 6 counts) and are labeled as compatible with the HFT600."}, {"q": "What type of filtration does the HFT600 use?", "a": "The HFT600 uses a wicking filter system, referred to as ''Filter T''. The provided listings do not specify a HEPA grade or exact physical dimensions for this filter."}]', 'The Honeywell Humidifier T HFT600 Blue White utilizes the official Filter T wicking filter. Listings confirm compatibility with the HFT600 model, as well as HEV615 and HEV620 variants. Both genuine Honeywell single-pack replacements and third-party multi-pack options are available for purchase. Buyers should verify their specific unit model to ensure correct fitment for this wicking filtration system.', '["The HFT600 model requires the ''Filter T'' wicking filter, which is also compatible with HEV615 and HEV620 units.", "Filtration is wicking-based; no HEPA grade or specific dimensional measurements are explicitly stated in the provided product titles.", "Consumers can choose between OEM Honeywell single packs and third-party value packs ranging from 3 to 6 filters."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'HRF201B U', 'honeywell-hrf201b-u-replacement-filter', 'air_purifier', 'honeywell hrf201b u filter', 'U', 'HEPA-Type', NULL, NULL, 'Verify your specific unit''s model sticker, as the Type U filter is compatible with HRF201B, HHT270, HHT290, and HHT270W, but may not fit other Honeywell variants. Ensure the part number matches the ''U'' designation to avoid ordering incorrect dimensions.', '[{"q": "What is the specific filter part code for the Honeywell HRF201B U?", "a": "The required filter is designated as the Type U or U Filter. It is compatible with Honeywell models HRF201B, HHT270, HHT290, and HHT270W."}, {"q": "Is there a difference between OEM and third-party filters for this model?", "a": "OEM filters are manufactured by Honeywell, while third-party options are replacements. Third-party listings often offer multi-packs (2, 4, or 6 units) and may include additional features like activated carbon, whereas OEM listings typically focus on single-unit authenticity."}, {"q": "What filtration features do these replacement filters provide?", "a": "The filters are HEPA-Type, designed to remove allergens and reduce odors. Some third-party variants are described as Dual Action HEPA-Type Activated Carbon filters, combining particulate filtration with carbon-based odor control."}]', 'The Honeywell HRF201B U utilizes a Type U HEPA filter, often referred to as a U Filter. This filtration component is designed to remove allergens and reduce odors. Both official Honeywell replacements and third-party multi-packs are available for this model, ensuring compatibility with HRF201B, HHT270, and HHT290 air purifier units.', '["The HRF201B U requires a Type U HEPA filter, which is cross-compatible with Honeywell HHT270, HHT290, and certain Febreze models.", "Listed filters feature HEPA-Type filtration, with some third-party options including activated carbon for dual-action odor reduction.", "Buying options range from single OEM units to high-value third-party packs containing 2, 4, or 6 filters."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), '16 X 25', 'honeywell-16-x-25-replacement-filter', 'air_purifier', 'honeywell 16 x 25 filter', 'FC100A1029', NULL, 'rectangular', '{"length_in": 16, "width_in": 25, "height_in": 4}', 'Verify that your specific Honeywell 16 X 25 unit requires the 4-inch depth filter, as listings distinguish between MERV 8 and MERV 11 grades. Ensure the part number FC100A1029 matches your device''s manual to avoid fitment issues.', '[{"q": "What is the official part number for the Honeywell 16 X 25 filter?", "a": "The official part number listed for the 16\" x 25\" x 4\" filter is FC100A1029."}, {"q": "Are there differences between OEM and third-party filters for this model?", "a": "The scraped listings show only genuine Honeywell products. OEM options include single units and multi-packs (2-pack, 5-pack) with MERV 11 or MERV 8 ratings."}, {"q": "What filtration features are available for the Honeywell 16 X 25?", "a": "Filters are available in MERV 11 and MERV 8 grades. Some MERV 11 bundles include a same-day supply filter change reminder feature."}]', 'The Honeywell 16 X 25 air purifier utilizes the FC100A1029 filter, a 16" x 25" x 4" pleated media unit. Listings confirm MERV 11 and MERV 8 filtration grades are available for this specific dimension. Consumers can purchase genuine Honeywell OEM units or multi-pack bundles, with some options including supply filter change reminders to maintain optimal airflow and indoor air quality.', '["The compatible filter part number is FC100A1029, with dimensions of 16 inches by 25 inches by 4 inches.", "Available filtration grades include MERV 11 for higher particle capture and MERV 8 for standard maintenance.", "Buying options include single OEM units and multi-pack bundles (2-pack and 5-pack) with filter change reminders."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
