INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'Fpr 7 Air 20X25X1', 'honeywell-fpr-7-air-20x25x1-replacement-filter', 'air_purifier', 'honeywell fpr 7 air filter 20x25x1', NULL, NULL, 'rectangular', '{"length_in": 20, "width_in": 25, "height_in": 1}', 'Verify that your specific Honeywell Fpr 7 Air unit requires a 20x25x1 inch filter by checking the model sticker, as dimensions vary across different air purifier models. Ensure the MERV rating matches your specific filtration needs, as MERV 8 and MERV 11 offer different levels of particle capture.', '[{"q": "What is the exact filter size for the Honeywell Fpr 7 Air 20X25X1?", "a": "The filter size is 20 inches in length, 25 inches in width, and 1 inch in height, as indicated by the 20x25x1 designation in compatible product listings."}, {"q": "Is the Honeywell 11000 filter the only option for this model?", "a": "No, while the Honeywell 11000 MERV 11 filter is an OEM option, third-party replacements such as Filtrete MERV 11, Aerostar MERV 11, and Filterbuy MERV 8 are also compatible based on the 20x25x1 dimensions."}, {"q": "What is the difference between MERV 8 and MERV 11 filters for this unit?", "a": "MERV 8 filters, like the Filterbuy option, provide basic dust and allergy defense, while MERV 11 filters, such as the Honeywell 11000 and Filtrete options, offer higher efficiency for reducing smaller allergens and particles."}]', 'The Honeywell Fpr 7 Air 20X25X1 utilizes a 20x25x1 inch rectangular filter. Available options include MERV 8 and MERV 11 filtration grades. While no specific official Honeywell part code is explicitly listed in the provided data, both OEM Honeywell 11000 series filters and third-party replacements from brands like Filtrete and Aerostar are available in multi-packs.', '["Compatible filters are rectangular with dimensions of 20 inches by 25 inches by 1 inch.", "Filtration options range from MERV 8 for basic dust defense to MERV 11 for enhanced allergen reduction.", "Buyers can choose between OEM Honeywell 4-packs and third-party value packs from brands such as Filtrete and Aerostar."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'Fpr 7 Air 16X20X1', 'honeywell-fpr-7-air-16x20x1-replacement-filter', 'air_purifier', 'honeywell fpr 7 air filter 16x20x1', NULL, NULL, 'rectangular', '{"length_in": 16, "width_in": 20, "height_in": 1}', 'Buyers should verify the exact model sticker or part number on their Honeywell FPR 7 unit, as some listings use generic dimensions or different MERV ratings that may not meet specific performance needs.', '[{"q": "What part number or code should I look for when buying a replacement filter for the Honeywell FPR 7 Air 16x20x1?", "a": "The listings do not provide a specific official part code; you need a 16×20×1 in rectangular filter that matches the FPR 7 model."}, {"q": "Is there a difference between Honeywell OEM filters and the third‑party packs shown?", "a": "Honeywell OEM filters are branded and listed with MERV 11, while third‑party packs are unbranded, typically MERV 8, and sold in larger quantities."}, {"q": "What filtration grades are available for this size filter and how often should they be replaced?", "a": "Available grades in the listings range from MERV 8 to MERV 11; replacement frequency depends on usage but generally every 3‑6 months for typical residential use."}]', 'The Honeywell FPR 7 Air 16x20x1 uses a 16×20×1‑inch rectangular filter; no specific part code is listed in the titles. Replacement options include Honeywell OEM filters and third‑party multi‑pack filters with MERV 8‑11 ratings. These filters are available in packs of two to six and provide allergen reduction for residential HVAC systems.', '["OEM Honeywell filter and third‑party packs both match the 16×20×1 in rectangular size required for the FPR 7.", "Listings show MERV 11 (Honeywell) and MERV 8 filters, indicating varying filtration efficiency.", "Multi‑pack options (2‑6 units) offer value, while OEM provides brand assurance."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'Fpr 7 Air 20X30X1', 'honeywell-fpr-7-air-20x30x1-replacement-filter', 'air_purifier', 'honeywell fpr 7 air filter 20x30x1', NULL, NULL, 'rectangular', '{"length_in": 20, "width_in": 30, "height_in": 1}', 'Verify your specific Honeywell Fpr 7 Air 20X30X1 model sticker to confirm the 20x30x1 dimension requirement. Note that third-party filters may have slightly smaller actual dimensions (e.g., 19.94"x29.94") to ensure proper fit.', '[{"q": "What is the exact filter size for the Honeywell Fpr 7 Air 20X30X1?", "a": "The required filter size is 20x30x1 inches. Some third-party listings specify actual dimensions of 19.94\"x29.94\"x0.75\" to accommodate frame fit."}, {"q": "Is the Honeywell 11000 filter the same as the Fpr 7 Air 20X30X1 filter?", "a": "The Honeywell 11000 is a MERV 11 filter in a 20x30x1 size, which matches the dimensions and filtration grade indicated for the Fpr 7 Air 20X30X1."}, {"q": "What filtration levels are available for this filter size?", "a": "Listings show options for MERV 8 (dust, pet, and allergy control) and MERV 11 (allergen reducer, comparable to MPR 1200)."}]', 'The Honeywell Fpr 7 Air 20X30X1 utilizes a 20x30x1 inch rectangular filter. Listings indicate compatibility with MERV 8 and MERV 11 filtration grades, including options comparable to MPR 1200. Both official Honeywell 4-packs and third-party value packs are available for this specific size and filtration standard.', '["Compatible filters are 20x30x1 inches, with actual dimensions often measuring 19.94\"x29.94\"x0.75\".", "Available filtration grades include MERV 8 for dust/pet control and MERV 11 for allergen reduction.", "Options range from official Honeywell 4-packs to third-party 2-pack and 6-pack value sets."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'Fpr 7 Air 14X24X1', 'honeywell-fpr-7-air-14x24x1-replacement-filter', 'air_purifier', 'honeywell fpr 7 air filter 14x24x1', NULL, NULL, 'rectangular', '{"length_in": 24, "width_in": 14, "height_in": 1}', 'Verify your system''s exact dimensions before purchasing, as actual sizes like 13.75"x23.75"x0.75" may vary from the 14x24x1 nominal size. Check your existing filter''s frame for specific model numbers or FPR ratings.', '[{"q": "Which filter code fits the Honeywell Fpr 7 Air 14X24X1?", "a": "This system uses standard 14x24x1 inch filters; while no specific alphanumeric part code is listed in the product titles, MERV 11 Honeywell filters are compatible."}, {"q": "What is the difference between OEM and third-party filters for this model?", "a": "Honeywell provides OEM MERV 11 filters, while third-party brands like Filterbuy and Aerostar offer MERV 8 or MERV 11 alternatives in bulk packs."}, {"q": "What filtration features are available for 14x24x1 replacements?", "a": "Available filters offer MERV 8 dust and allergy defense or MERV 11 allergen reduction to control pet dander and fine particles."}]', 'The Honeywell Fpr 7 Air 14X24X1 requires a 14x24x1 inch replacement filter. Options include official Honeywell MERV 11 allergen reducers and third-party alternatives from brands like Filterbuy, Aerostar, and Simply. These filters are available in MERV 8 and MERV 11 grades, often sold in value-oriented four-packs for HVAC maintenance.', '["Compatible with 14x24x1 inch nominal size filters for HVAC and furnace systems.", "Available in MERV 8 for dust/allergy defense or MERV 11 for enhanced allergen reduction.", "Options include genuine Honeywell OEM filters and cost-effective third-party multi-packs."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
