INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), '20X25X5 Merv 8', 'honeywell-20x25x5-merv-8-replacement-filter', 'air_purifier', 'honeywell 20x25x5 merv 8 replacement filter', 'FC100A1037', NULL, 'rectangular', '{"length_in": 20, "width_in": 25, "height_in": 5}', 'Verify that your specific Honeywell unit requires a 20x25x5 MERV 8 filter, as dimensions and ratings vary by model. Cross-reference the part number FC100A1037 if applicable to your specific system variant.', '[{"q": "What is the compatible part number for the Honeywell 20X25X5 Merv 8 filter?", "a": "Listings indicate that part number FC100A1037 is a compatible fit for Honeywell systems using this filter size and rating."}, {"q": "Are there OEM Honeywell filters available in these listings?", "a": "No, the provided listings feature third-party replacements from Filterbuy, AIRx, and Nordic Pure. No official Honeywell branded units are included in this specific dataset."}, {"q": "What filtration features do these 20x25x5 MERV 8 filters provide?", "a": "These filters are designed for dust and allergy defense, meeting MERV 8 standards for capturing common airborne particles."}]', 'The Honeywell 20X25X5 Merv 8 air purifier utilizes a rectangular 20x25x5 inch filter. Listings identify FC100A1037 as a compatible part number. Available options include third-party replacements from brands like Filterbuy, AIRx, and Nordic Pure. These filters provide MERV 8 filtration for dust and allergy defense. Both single and multi-pack configurations are available for purchase.', '["Compatible filters measure 20x25x5 inches and meet MERV 8 standards for dust and allergy defense.", "Part number FC100A1037 is explicitly listed as a fit for Honeywell systems in third-party listings.", "Third-party brands offer 2-pack and 4-pack value options, while no official Honeywell OEM units appear in the provided data."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), '16X25X5 Merv 8', 'honeywell-16x25x5-merv-8-replacement-filter', 'air_purifier', 'honeywell 16x25x5 merv 8 replacement filter', 'FC100A1029', NULL, 'rectangular', '{"length_in": 16, "width_in": 25, "height_in": 5}', 'Verify your specific Honeywell 16X25X5 Merv 8 model sticker to ensure the 16x25x5 dimension matches your unit, as listings include both MERV 8 and MERV 11 filtration grades. Confirm whether you require the specific FC100A1029 part number or a generic dimensional replacement.', '[{"q": "What is the official Honeywell filter part number for the 16X25X5 Merv 8?", "a": "The AIRx Filters listing identifies FC100A1029 as a replacement part number for the Honeywell 16X25X5 Merv 8 filter."}, {"q": "Are there OEM Honeywell filters available in these listings?", "a": "No, the provided listings feature third-party replacements from Filterbuy, Filtrete, and AIRx. While AIRx lists Honeywell part numbers, the products are not manufactured by Honeywell."}, {"q": "What filtration features do the 16x25x5 MERV 8 replacements offer?", "a": "The MERV 8 replacements from Filterbuy and AIRx provide dust and allergy defense, with AIRx specifically noting dust and pollen control capabilities."}]', 'The Honeywell 16X25X5 Merv 8 air purifier accepts rectangular filters measuring 16 by 25 by 5 inches. Listings identify FC100A1029 as a compatible official filter code. Available options include MERV 8 third-party replacements from brands like Filterbuy and AIRx, as well as higher-rated MERV 11 alternatives. Both single and multi-pack configurations are available for purchase.', '["Compatible filters measure 16x25x5 inches and include MERV 8 and MERV 11 filtration grades.", "Third-party brands such as Filterbuy and AIRx offer replacements, with AIRx explicitly listing Honeywell part number FC100A1029 compatibility.", "Purchase options range from 2-packs and 4-packs of MERV 8 filters to 2-packs of MERV 11 filters."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'Merv 8', 'honeywell-merv-8-replacement-filter', 'air_purifier', 'honeywell merv 8 filter', NULL, NULL, NULL, NULL, 'Verify the exact dimensions and part number on your existing filter or unit sticker, as listings show varying sizes such as 16x25x4 and 20x25x5. Do not assume a single part number fits all Honeywell Merv 8 models without checking specific compatibility.', '[{"q": "What is the official part number for Honeywell Merv 8 filters?", "a": "The provided listings do not explicitly state a single official Honeywell part number for the Merv 8 filter. One third-party listing references compatibility with Honeywell FC100A1037, but this is not confirmed as the universal OEM code for all Merv 8 units."}, {"q": "Are third-party Merv 8 filters compatible with Honeywell systems?", "a": "Yes, listings show third-party brands like AIRx and Nordic Pure offering Merv 8 filters that fit Honeywell systems. For example, AIRx filters are listed as fitting Honeywell FC100A1037, and Nordic Pure offers Honeywell/Lennox replacements."}, {"q": "What filtration grade do these Honeywell Merv 8 filters provide?", "a": "All listed products specify a MERV 8 filtration grade. This rating indicates the filter''s ability to capture fine particles, though no HEPA grade is mentioned in the titles."}]', 'Replacement filters for the Honeywell Merv 8 include OEM Honeywell Home units and third-party alternatives like AIRx and Nordic Pure. Listings specify MERV 8 filtration grade but do not provide a single universal official part code. Available dimensions vary by listing, including 16x25x4 and 20x25x5 inches. Buyers should verify their specific unit''s required size and part number to ensure compatibility with their Honeywell air purifier or furnace system.', '["Listings confirm MERV 8 filtration grade for both OEM Honeywell Home and third-party brands like AIRx and Nordic Pure.", "Dimensions vary across products, with specific sizes including 16x25x4 inches and 20x25x5 inches, requiring precise measurement for fit.", "OEM Honeywell Home filters are sold in 3-packs, while third-party options offer 2-packs or 3-packs, providing different value propositions."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
