INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'blueair'), 'Purifier 411', 'blueair-purifier-411-replacement-filter', 'air_purifier', 'blueair purifier filter 411', NULL, NULL, NULL, NULL, 'Verify your specific unit is a Blueair 411, 411+, or 411 Auto, as listings distinguish these variants from the 411i Max and 411a Max models. Do not assume cross-compatibility with Max series filters without checking the model sticker.', '[{"q": "What filter part code fits the Blueair Purifier 411?", "a": "The provided listings do not explicitly state a specific alphanumeric part code, but confirm compatibility with the 411, 411+, and 411 Auto series."}, {"q": "Is the Blue Pure filter an OEM replacement for the Blueair 411?", "a": "No, the Blue Pure filter is a third-party replacement, whereas the ''BLUEAIR Genuine'' filter is the OEM option."}, {"q": "What filtration features are specified for the Blueair 411 filter?", "a": "The listings mention ''Everyday'' filtration for the genuine filter but do not specify HEPA grades or other technical filtration metrics in the titles."}]', 'The Blueair Purifier 411 utilizes replacement filters compatible with the 411, 411+, and 411 Auto models. Listings indicate availability of genuine Blueair filters and third-party replacements from Blue Pure. Specific filtration grades and official part codes are not explicitly detailed in the provided product titles. Buyers can select between single OEM units or multi-pack third-party options for maintenance.', '["Filters are explicitly compatible with Blueair 411, 411+, and 411 Auto air purifier models.", "Both genuine Blueair OEM filters and third-party Blue Pure replacements are available in the market.", "Specific HEPA grades and physical dimensions are not stated in the provided product titles."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'blueair'), '2 In 1', 'blueair-2-in-1-replacement-filter', 'air_purifier', 'blueair 2 in 1 replacement filter', 'DH3i', NULL, NULL, NULL, 'Verify that your specific Blueair 2 In 1 unit is labeled for the DH3i filter system, as the listings specify compatibility with the ''Purify + Humidify'' variant. Ensure the model sticker matches the DH3i designation to avoid ordering incompatible filters for other Blueair models.', '[{"q": "What is the correct filter part number for the Blueair 2 In 1?", "a": "The correct filter part number is DH3i, which is explicitly cited in the titles of both OEM and third-party replacement listings for the Blueair 2 In 1 Purify + Humidify air purifier."}, {"q": "Is there a difference between OEM and third-party filters for this model?", "a": "Yes, OEM filters are manufactured by Blueair and are labeled as ''Genuine,'' while third-party options are labeled as ''Compatible'' or ''Replacement.'' Third-party listings often offer multi-packs containing both particle and wick filters, whereas the OEM listing specifically highlights the wick filter."}, {"q": "What filtration features do the DH3i filters provide?", "a": "The DH3i filters are designed for dual functionality, capturing water minerals and delivering pure water humidification in addition to standard air purification. The system utilizes separate particle filters and wick filters to maintain both air quality and humidity levels."}]', 'The Blueair 2 In 1 air purifier utilizes the DH3i filter system, which includes both particle and wick components for combined purification and humidification. While specific HEPA grades are not explicitly detailed in the provided listings, the DH3i code is the primary identifier for compatibility. Both genuine OEM wick filters and third-party multi-pack replacements containing particle and wick elements are available for this model.', '["The DH3i filter code is the specific identifier for replacement filters compatible with the Blueair 2 In 1 Purify + Humidify unit.", "Filtration systems for this model include distinct particle filters and wick filters designed to capture water minerals and deliver pure water humidification.", "Consumers can choose between genuine Blueair OEM wick filters and third-party value packs that bundle multiple particle filters with wick replacements."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
